{"filePath": "/app/server.js", "content": "const express = require('express');
const { Pool } = require('pg');
require('dotenv').config();

const app = express();
const port = Number(process.env.APPLICATION_PORT || 8000);
const pool = new Pool({ connectionString: process.env.POSTGRES_DATABASE_URL });
const barbers = ['Alex', 'Lucy', 'George'];
const openHour = 9;
const closeHour = 18;

app.use(express.json());
app.use(express.static('public'));

function isValidDate(value) {
  return /^\d{4}-\d{2}-\d{2}$/.test(value) && !Number.isNaN(Date.parse(`${value}T00:00:00Z`));
}

function isValidTime(value) {
  if (!/^\d{2}:\d{2}$/.test(value)) return false;
  const [hour, minute] = value.split(':').map(Number);
  return hour >= openHour && hour < closeHour && (minute === 0 || minute === 30);
}

function endTime(startTime) {
  const [hour, minute] = startTime.split(':').map(Number);
  const total = hour * 60 + minute + 30;
  return `${String(Math.floor(total / 60)).padStart(2, '0')}:${String(total % 60).padStart(2, '0')}`;
}

function rowToAppointment(row) {
  return {
    id: row.id,
    date: row.appointment_date,
    startTime: row.start_time.slice(0, 5),
    endTime: endTime(row.start_time.slice(0, 5)),
    barber: row.barber,
    customerName: row.customer_name,
    notes: row.notes || '',
  };
}

app.get('/api/config', (_req, res) => {
  res.json({ timezone: 'UTC', hours: '09:00-18:00', slotDurationMinutes: 30, barbers });
});

app.get('/api/appointments', async (req, res, next) => {
  try {
    const date = String(req.query.date || '');
    if (!isValidDate(date)) return res.status(400).json({ error: 'Valid date is required.' });
    const result = await pool.query(
      `select id, to_char(appointment_date, 'YYYY-MM-DD') as appointment_date, start_time::text, barber, customer_name, notes
       from appointments where appointment_date = $1 order by start_time, barber`,
      [date]
    );
    res.json(result.rows.map(rowToAppointment));
  } catch (error) {
    next(error);
  }
});

app.post('/api/appointments', async (req, res, next) => {
  try {
    const { date, startTime, barber, customerName, notes } = req.body;
    if (!isValidDate(date) || !isValidTime(startTime) || !barbers.includes(barber)) {
      return res.status(400).json({ error: 'Invalid appointment slot.' });
    }
    if (!String(customerName || '').trim()) {
      return res.status(400).json({ error: 'Customer name is required.' });
    }
    const result = await pool.query(
      `insert into appointments (appointment_date, start_time, barber, customer_name, notes)
       values ($1, $2, $3, $4, $5)
       returning id, to_char(appointment_date, 'YYYY-MM-DD') as appointment_date, start_time::text, barber, customer_name, notes`,
      [date, startTime, barber, String(customerName).trim(), String(notes || '').trim()]
    );
    res.status(201).json(rowToAppointment(result.rows[0]));
  } catch (error) {
    if (error.code === '23505') return res.status(409).json({ error: 'That slot was just booked. Choose another slot.' });
    next(error);
  }
});

app.patch('/api/appointments/:id', async (req, res, next) => {
  try {
    const { customerName, notes } = req.body;
    if (!String(customerName || '').trim()) {
      return res.status(400).json({ error: 'Customer name is required.' });
    }
    const result = await pool.query(
      `update appointments set customer_name = $1, notes = $2, updated_at = now()
       where id = $3
       returning id, to_char(appointment_date, 'YYYY-MM-DD') as appointment_date, start_time::text, barber, customer_name, notes`,
      [String(customerName).trim(), String(notes || '').trim(), req.params.id]
    );
    if (!result.rowCount) return res.status(404).json({ error: 'Appointment not found.' });
    res.json(rowToAppointment(result.rows[0]));
  } catch (error) {
    next(error);
  }
});

app.delete('/api/appointments/:id', async (req, res, next) => {
  try {
    const result = await pool.query('delete from appointments where id = $1', [req.params.id]);
    if (!result.rowCount) return res.status(404).json({ error: 'Appointment not found.' });
    res.status(204).end();
  } catch (error) {
    next(error);
  }
});

app.use((error, _req, res, _next) => {
  console.error(error);
  res.status(500).json({ error: 'Server error.' });
});

app.listen(port, '0.0.0.0', () => {
  console.log(`Barber scheduler listening on ${port}`);
});
"}

{"filePath": "/app/scripts/setup-db.js", "content": "const { Pool } = require('pg');
require('dotenv').config();

async function main() {
  const pool = new Pool({ connectionString: process.env.POSTGRES_DATABASE_URL });
  await pool.query(`
    create table if not exists appointments (
      id serial primary key,
      appointment_date date not null,
      start_time time not null,
      barber text not null check (barber in ('Alex', 'Lucy', 'George')),
      customer_name text not null check (length(trim(customer_name)) > 0),
      notes text not null default '',
      created_at timestamptz not null default now(),
      updated_at timestamptz not null default now(),
      unique (appointment_date, start_time, barber)
    );
  `);
  await pool.end();
}

main().catch((error) => {
  console.error(error);
  process.exit(1);
});
"}

