{"filePath": "/app/public/app.js", "content": "const barbers = ['Alex', 'Lucy', 'George'];
const schedule = document.querySelector('#schedule');
const dateInput = document.querySelector('#schedule-date');
const selectedDateTitle = document.querySelector('#selected-date');
const message = document.querySelector('#message');
const dialog = document.querySelector('#appointment-dialog');
const form = document.querySelector('#appointment-form');
const dialogMode = document.querySelector('#dialog-mode');
const dialogTitle = document.querySelector('#dialog-title');
const detailDate = document.querySelector('#detail-date');
const detailTime = document.querySelector('#detail-time');
const detailBarber = document.querySelector('#detail-barber');
const customerName = document.querySelector('#customer-name');
const notes = document.querySelector('#notes');
const formError = document.querySelector('#form-error');
const cancelButton = document.querySelector('#cancel-appointment');
const closeDialog = document.querySelector('#close-dialog');
const dismissDialog = document.querySelector('#dismiss-dialog');
let appointments = [];
let currentSlot = null;

function todayUtc() {
  return new Date().toISOString().slice(0, 10);
}

function slots() {
  const values = [];
  for (let total = 9 * 60; total < 18 * 60; total += 30) {
    values.push(`${String(Math.floor(total / 60)).padStart(2, '0')}:${String(total % 60).padStart(2, '0')}`);
  }
  return values;
}

function endTime(startTime) {
  const [hour, minute] = startTime.split(':').map(Number);
  const total = hour * 60 + minute + 30;
  return `${String(Math.floor(total / 60)).padStart(2, '0')}:${String(total % 60).padStart(2, '0')}`;
}

function showMessage(text, isError = false) {
  message.textContent = text;
  message.classList.toggle('error', isError);
  message.hidden = !text;
}

function showFormError(text) {
  formError.textContent = text;
  formError.hidden = !text;
}

function renderSchedule() {
  selectedDateTitle.textContent = `Schedule for ${dateInput.value}`;
  schedule.innerHTML = '';
  const corner = document.createElement('div');
  corner.className = 'corner-cell';
  corner.textContent = 'Time';
  corner.dataset.testid = 'text-time-header';
  schedule.append(corner);
  barbers.forEach((barber) => {
    const head = document.createElement('div');
    head.className = 'barber-head';
    head.textContent = barber;
    head.dataset.testid = `text-barber-${barber}`;
    schedule.append(head);
  });

  slots().forEach((time) => {
    const timeCell = document.createElement('div');
    timeCell.className = 'time-cell';
    timeCell.textContent = time;
    timeCell.dataset.testid = `text-time-${time.replace(':', '')}`;
    schedule.append(timeCell);

    barbers.forEach((barber) => {
      const appointment = appointments.find((item) => item.startTime === time && item.barber === barber);
      const cell = document.createElement('div');
      cell.className = 'cell';
      cell.dataset.testid = `cell-slot-${barber}-${time.replace(':', '')}`;
      const button = document.createElement('button');
      button.type = 'button';
      button.className = `slot-button ${appointment ? 'booked' : 'available'}`;
      button.dataset.testid = `${appointment ? 'button-view' : 'button-book'}-${barber}-${time.replace(':', '')}`;
      button.innerHTML = appointment
        ? `<span class="slot-title" data-testid="text-customer-${appointment.id}"></span><span class="slot-subtitle" data-testid="text-slot-${appointment.id}">${time}-${appointment.endTime}</span>`
        : `<span class="slot-title" data-testid="text-available-${barber}-${time.replace(':', '')}">Available</span><span class="slot-subtitle" data-testid="text-slot-empty-${barber}-${time.replace(':', '')}">${time}-${endTime(time)}</span>`;
      if (appointment) button.querySelector('.slot-title').textContent = appointment.customerName;
      button.addEventListener('click', () => openDialog({ date: dateInput.value, time, barber, appointment }));
      cell.append(button);
      schedule.append(cell);
    });
  });
}

async function loadAppointments() {
  showMessage('');
  const response = await fetch(`/api/appointments?date=${encodeURIComponent(dateInput.value)}`);
  if (!response.ok) throw new Error('Could not load appointments.');
  appointments = await response.json();
  renderSchedule();
}

function openDialog({ date, time, barber, appointment }) {
  currentSlot = { date, startTime: time, barber, appointment };
  const editing = Boolean(appointment);
  dialogMode.textContent = editing ? 'Appointment details' : 'New appointment';
  dialogTitle.textContent = editing ? appointment.customerName : 'Book slot';
  detailDate.textContent = date;
  detailTime.textContent = `${time}-${editing ? appointment.endTime : endTime(time)}`;
  detailBarber.textContent = barber;
  customerName.value = editing ? appointment.customerName : '';
  notes.value = editing ? appointment.notes : '';
  cancelButton.hidden = !editing;
  showFormError('');
  dialog.showModal();
  customerName.focus();
}

async function saveAppointment(event) {
  event.preventDefault();
  showFormError('');
  const name = customerName.value.trim();
  if (!name) {
    showFormError('Customer name is required.');
    return;
  }
  const editing = Boolean(currentSlot.appointment);
  const url = editing ? `/api/appointments/${currentSlot.appointment.id}` : '/api/appointments';
  const method = editing ? 'PATCH' : 'POST';
  const body = editing
    ? { customerName: name, notes: notes.value }
    : { date: currentSlot.date, startTime: currentSlot.startTime, barber: currentSlot.barber, customerName: name, notes: notes.value };
  const response = await fetch(url, { method, headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body) });
  const result = response.status === 204 ? null : await response.json().catch(() => null);
  if (!response.ok) {
    showFormError(result?.error || 'Unable to save appointment.');
    return;
  }
  dialog.close();
  showMessage(editing ? 'Appointment updated.' : 'Appointment booked.');
  await loadAppointments();
}

async function cancelAppointment() {
  if (!currentSlot.appointment) return;
  if (!confirm('Cancel this appointment?')) return;
  const response = await fetch(`/api/appointments/${currentSlot.appointment.id}`, { method: 'DELETE' });
  if (!response.ok) {
    const result = await response.json().catch(() => null);
    showFormError(result?.error || 'Unable to cancel appointment.');
    return;
  }
  dialog.close();
  showMessage('Appointment cancelled.');
  await loadAppointments();
}

dateInput.value = todayUtc();
dateInput.addEventListener('change', () => loadAppointments().catch((error) => showMessage(error.message, true)));
form.addEventListener('submit', (event) => saveAppointment(event).catch(() => showFormError('Unable to save appointment.')));
cancelButton.addEventListener('click', () => cancelAppointment().catch(() => showFormError('Unable to cancel appointment.')));
closeDialog.addEventListener('click', () => dialog.close());
dismissDialog.addEventListener('click', () => dialog.close());
loadAppointments().catch((error) => showMessage(error.message, true));
"}

