{"filePath": "/app/src/main.tsx", "content": "import React, { useMemo, useState } from 'react'
import { createRoot } from 'react-dom/client'
import './styles.css'

type Question = {
  id: string
  question: string
  option_a: string
  option_b: string
  option_c: string
  option_d: string
  correct_option: 'A' | 'B' | 'C' | 'D'
  explanation: string
  category: string
}

type GameState = 'categories' | 'warning' | 'playing' | 'results'

type AnswerRecord = {
  questionId: string
  selected: 'A' | 'B' | 'C' | 'D'
  correct: boolean
}

const optionKeys = ['A', 'B', 'C', 'D'] as const
const optionFields = {
  A: 'option_a',
  B: 'option_b',
  C: 'option_c',
  D: 'option_d',
} as const

function parseCsv(source: string) {
  const rows: string[][] = []
  let row: string[] = []
  let cell = ''
  let quoted = false

  for (let index = 0; index < source.length; index += 1) {
    const char = source[index]
    const next = source[index + 1]
    if (char === '"') {
      if (quoted && next === '"') {
        cell += '"'
        index += 1
      } else {
        quoted = !quoted
      }
    } else if (char === ',' && !quoted) {
      row.push(cell)
      cell = ''
    } else if ((char === '\n' || char === '\r') && !quoted) {
      if (char === '\r' && next === '\n') index += 1
      row.push(cell)
      if (row.some((value) => value.length > 0)) rows.push(row)
      row = []
      cell = ''
    } else {
      cell += char
    }
  }

  row.push(cell)
  if (row.some((value) => value.length > 0)) rows.push(row)

  const headers = rows[0]
  return rows.slice(1).map((values) =>
    Object.fromEntries(headers.map((header, index) => [header, values[index] ?? ''])) as Question,
  )
}

function shuffle<T>(items: T[]) {
  const result = [...items]
  for (let index = result.length - 1; index > 0; index -= 1) {
    const swapIndex = Math.floor(Math.random() * (index + 1))
    ;[result[index], result[swapIndex]] = [result[swapIndex], result[index]]
  }
  return result
}

function App() {
  const [questions, setQuestions] = useState<Question[]>([])
  const [state, setState] = useState<GameState>('categories')
  const [selectedCategory, setSelectedCategory] = useState('')
  const [surpriseCategory, setSurpriseCategory] = useState('')
  const [gameQuestions, setGameQuestions] = useState<Question[]>([])
  const [currentIndex, setCurrentIndex] = useState(0)
  const [selectedAnswer, setSelectedAnswer] = useState<'A' | 'B' | 'C' | 'D' | ''>('')
  const [submitted, setSubmitted] = useState(false)
  const [answers, setAnswers] = useState<AnswerRecord[]>([])
  const [streak, setStreak] = useState(0)
  const [maxStreak, setMaxStreak] = useState(0)
  const [startedAt, setStartedAt] = useState(0)
  const [elapsedSeconds, setElapsedSeconds] = useState(0)
  const [loadError, setLoadError] = useState('')

  React.useEffect(() => {
    fetch('/questions.csv')
      .then((response) => {
        if (!response.ok) throw new Error('Unable to load questions')
        return response.text()
      })
      .then((text) => setQuestions(parseCsv(text)))
      .catch(() => setLoadError('Unable to load quiz questions'))
  }, [])

  const categories = useMemo(
    () => [...new Set(questions.map((question) => question.category))].sort(),
    [questions],
  )

  const currentQuestion = gameQuestions[currentIndex]
  const score = answers.filter((answer) => answer.correct).length
  const achievements = [
    gameQuestions.length === 10 && score === gameQuestions.length ? 'Perfect Round' : '',
    maxStreak >= 5 ? 'Hot Streak' : '',
    maxStreak >= 3 ? 'Triple Win' : '',
  ].filter(Boolean)

  function questionsFor(category: string) {
    return questions.filter((question) => question.category === category)
  }

  function chooseCategory(category: string) {
    const actualCategory = category === 'Surprise Me!' ? categories[Math.floor(Math.random() * categories.length)] : category
    setSelectedCategory(actualCategory)
    setSurpriseCategory(category === 'Surprise Me!' ? actualCategory : '')
    if (questionsFor(actualCategory).length < 10) {
      setState('warning')
      return
    }
    startGame(actualCategory)
  }

  function startGame(category = selectedCategory) {
    setGameQuestions(shuffle(questionsFor(category)).slice(0, 10))
    setCurrentIndex(0)
    setSelectedAnswer('')
    setSubmitted(false)
    setAnswers([])
    setStreak(0)
    setMaxStreak(0)
    setElapsedSeconds(0)
    setStartedAt(Date.now())
    setState('playing')
  }

  function submitAnswer() {
    if (!selectedAnswer || !currentQuestion) return
    const correct = selectedAnswer === currentQuestion.correct_option
    const nextStreak = correct ? streak + 1 : 0
    setStreak(nextStreak)
    setMaxStreak((value) => Math.max(value, nextStreak))
    setAnswers((value) => [...value, { questionId: currentQuestion.id, selected: selectedAnswer, correct }])
    setSubmitted(true)
  }

  function advance() {
    if (currentIndex === gameQuestions.length - 1) {
      setElapsedSeconds(Math.max(1, Math.round((Date.now() - startedAt) / 1000)))
      setState('results')
      return
    }
    setCurrentIndex((value) => value + 1)
    setSelectedAnswer('')
    setSubmitted(false)
  }

  function newCategory() {
    setState('categories')
    setSelectedCategory('')
    setSurpriseCategory('')
  }

  return (
    <main className="app-shell">
      <section className="hero" data-testid="section-quiz-app">
        <div>
          <p className="eyebrow" data-testid="text-app-label">Quiz Quest MVP</p>
          <h1 data-testid="text-title">Challenge your knowledge</h1>
          <p className="subtitle" data-testid="text-subtitle">Pick a category, answer up to 10 questions, and unlock achievements with every hot streak.</p>
        </div>
        <div className="score-orb" data-testid="text-category-count">{categories.length || 0} categories</div>
      </section>

      {loadError && <div className="panel alert" data-testid="status-load-error">{loadError}</div>}

      {state === 'categories' && !loadError && (
        <section className="panel" data-testid="section-category-selection">
          <div className="section-heading">
            <h2 data-testid="text-select-category">Select a category</h2>
            <p data-testid="text-category-helper">Geography and Science have full 10-question rounds. Every category is available.</p>
          </div>
          <div className="category-grid">
            <button className="category-card surprise" onClick={() => chooseCategory('Surprise Me!')} disabled={!categories.length} data-testid="button-category-surprise">
              <span data-testid="text-category-surprise">Surprise Me!</span>
              <small data-testid="text-category-surprise-desc">Randomly pick a category</small>
            </button>
            {categories.map((category) => (
              <button className="category-card" key={category} onClick={() => chooseCategory(category)} data-testid={`button-category-${category}`}>
                <span data-testid={`text-category-name-${category}`}>{category}</span>
                <small data-testid={`text-category-count-${category}`}>{questionsFor(category).length} questions</small>
              </button>
            ))}
          </div>
        </section>
      )}

      {state === 'warning' && (
        <section className="panel centered" data-testid="section-warning">
          <p className="eyebrow" data-testid="text-warning-category">{surpriseCategory ? `Surprise selected: ${surpriseCategory}` : selectedCategory}</p>
          <h2 data-testid="text-warning-title">Not enough questions in this category for all accomplishments</h2>
          <p data-testid="text-warning-detail">This round will include {questionsFor(selectedCategory).length} questions, so Perfect Round may not be possible.</p>
          <div className="actions">
            <button onClick={() => startGame()} data-testid="button-proceed-anyway">Proceed anyway</button>
            <button className="ghost" onClick={newCategory} data-testid="button-change-category">Choose another category</button>
          </div>
        </section>
      )}

      {state === 'playing' && currentQuestion && (
        <section className="panel quiz-panel" data-testid="section-gameplay">
          {surpriseCategory && <p className="notice" data-testid="text-surprise-selected">Surprise Me selected: {surpriseCategory}</p>}
          <div className="quiz-topline">
            <span data-testid="text-progress">Question {currentIndex + 1} of {gameQuestions.length}</span>
            <span data-testid="text-current-category">{selectedCategory}</span>
          </div>
          <div className="progress-track" data-testid="status-progress-bar"><span style={{ width: `${((currentIndex + 1) / gameQuestions.length) * 100}%` }} /></div>
          <h2 className="question" data-testid="text-question">{currentQuestion.question}</h2>
          <div className="options">
            {optionKeys.map((key) => {
              const isCorrect = key === currentQuestion.correct_option
              const isSelected = key === selectedAnswer
              const className = submitted && isCorrect ? 'option correct' : submitted && isSelected ? 'option wrong' : isSelected ? 'option selected' : 'option'
              return (
                <button key={key} className={className} onClick={() => setSelectedAnswer(key)} disabled={submitted} data-testid={`button-answer-${key}`}>
                  <b data-testid={`text-option-label-${key}`}>{key}</b>
                  <span data-testid={`text-option-${key}`}>{currentQuestion[optionFields[key]]}</span>
                </button>
              )
            })}
          </div>
          {submitted && (
            <div className="feedback" data-testid="section-feedback">
              <h3 data-testid="status-answer-result">{selectedAnswer === currentQuestion.correct_option ? 'Correct!' : 'Incorrect'}</h3>
              <p data-testid="text-explanation">{currentQuestion.explanation}</p>
            </div>
          )}
          <div className="actions split">
            <span data-testid="text-streak">Current streak: {streak}</span>
            {!submitted ? (
              <button onClick={submitAnswer} disabled={!selectedAnswer} data-testid="button-submit-answer">Submit Answer</button>
            ) : (
              <button onClick={advance} data-testid={currentIndex === gameQuestions.length - 1 ? 'button-see-results' : 'button-next-question'}>
                {currentIndex === gameQuestions.length - 1 ? 'See Results' : 'Next Question'}
              </button>
            )}
          </div>
        </section>
      )}

      {state === 'results' && (
        <section className="panel results" data-testid="section-results">
          <p className="eyebrow" data-testid="text-results-category">{selectedCategory}</p>
          <h2 data-testid="text-score">{score}/{gameQuestions.length} Correct ({Math.round((score / gameQuestions.length) * 100)}%)</h2>
          <p data-testid="text-elapsed-time">Elapsed time: {elapsedSeconds} seconds</p>
          <div className="achievement-box" data-testid="section-achievements">
            <h3 data-testid="text-achievements-title">Achievements</h3>
            {achievements.length ? achievements.map((achievement) => <span className="badge" key={achievement} data-testid={`text-achievement-${achievement}`}>{achievement}</span>) : <p data-testid="text-no-achievements">No achievements this round</p>}
          </div>
          <div className="actions">
            <button onClick={() => startGame(selectedCategory)} data-testid="button-play-again">Play Again</button>
            <button className="ghost" onClick={newCategory} data-testid="button-new-category">New Category</button>
          </div>
        </section>
      )}
    </main>
  )
}

createRoot(document.getElementById('root')!).render(<App />)
"}

{"filePath": "/app/src/styles.css", "content": ":root {
  color: #102033;
  font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  background: #eef4ff;
  font-synthesis: none;
  text-rendering: optimizeLegibility;
  -webkit-font-smoothing: antialiased;
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  min-width: 320px;
  min-height: 100vh;
  background:
    radial-gradient(circle at 15% 10%, rgba(125, 92, 255, 0.34), transparent 28rem),
    radial-gradient(circle at 85% 20%, rgba(0, 203, 255, 0.28), transparent 24rem),
    linear-gradient(135deg, #f7fbff 0%, #e9f0ff 46%, #f9f4ff 100%);
}

button {
  border: 0;
  border-radius: 999px;
  padding: 0.85rem 1.25rem;
  color: white;
  font: inherit;
  font-weight: 800;
  background: linear-gradient(135deg, #635bff, #00a6ff);
  box-shadow: 0 16px 35px rgba(64, 91, 255, 0.22);
  cursor: pointer;
  transition: transform 0.18s ease, box-shadow 0.18s ease, opacity 0.18s ease;
}

button:hover:not(:disabled) {
  transform: translateY(-2px);
  box-shadow: 0 20px 45px rgba(64, 91, 255, 0.3);
}

button:disabled {
  cursor: not-allowed;
  opacity: 0.48;
}

.app-shell {
  width: min(1100px, calc(100% - 2rem));
  margin: 0 auto;
  padding: 2rem 0;
}

.hero {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 2rem;
  margin-bottom: 1.5rem;
  padding: 2rem;
  color: white;
  border-radius: 2rem;
  background: linear-gradient(135deg, #131a3a, #29317a 48%, #5b3ee4);
  box-shadow: 0 28px 80px rgba(24, 35, 90, 0.3);
}

h1, h2, h3, p {
  margin-top: 0;
}

h1 {
  margin-bottom: 0.7rem;
  font-size: clamp(2.1rem, 5vw, 4.7rem);
  line-height: 0.95;
  letter-spacing: -0.06em;
}

h2 {
  margin-bottom: 0.6rem;
  font-size: clamp(1.7rem, 3vw, 2.5rem);
  letter-spacing: -0.04em;
}

.subtitle {
  max-width: 650px;
  margin-bottom: 0;
  color: rgba(255, 255, 255, 0.77);
  font-size: 1.08rem;
}

.eyebrow {
  margin-bottom: 0.75rem;
  color: #20d8ff;
  font-size: 0.78rem;
  font-weight: 900;
  letter-spacing: 0.16em;
  text-transform: uppercase;
}

.score-orb {
  display: grid;
  width: 9rem;
  height: 9rem;
  flex: 0 0 auto;
  place-items: center;
  border: 1px solid rgba(255, 255, 255, 0.25);
  border-radius: 50%;
  background: rgba(255, 255, 255, 0.12);
  color: white;
  font-weight: 900;
  text-align: center;
  backdrop-filter: blur(14px);
}

.panel {
  padding: clamp(1.2rem, 3vw, 2rem);
  border: 1px solid rgba(83, 103, 163, 0.14);
  border-radius: 1.8rem;
  background: rgba(255, 255, 255, 0.78);
  box-shadow: 0 24px 70px rgba(38, 56, 105, 0.14);
  backdrop-filter: blur(18px);
}

.alert {
  color: #8a1c30;
  background: #fff1f3;
}

.section-heading {
  display: flex;
  align-items: end;
  justify-content: space-between;
  gap: 1rem;
  margin-bottom: 1.3rem;
}

.section-heading p {
  max-width: 470px;
  margin-bottom: 0;
  color: #5d6b82;
}

.category-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(210px, 1fr));
  gap: 1rem;
}

.category-card {
  min-height: 8.5rem;
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  justify-content: space-between;
  border-radius: 1.35rem;
  padding: 1.25rem;
  color: #16223c;
  background: linear-gradient(145deg, #ffffff, #eef5ff);
  box-shadow: inset 0 0 0 1px rgba(69, 87, 140, 0.08), 0 18px 35px rgba(40, 54, 95, 0.1);
  text-align: left;
}

.category-card span {
  font-size: 1.25rem;
  font-weight: 900;
}

.category-card small {
  color: #68778f;
  font-weight: 800;
}

.category-card.surprise {
  color: white;
  background: linear-gradient(135deg, #ff7b7b, #7c4dff 55%, #00b8ff);
}

.category-card.surprise small {
  color: rgba(255, 255, 255, 0.82);
}

.centered {
  max-width: 720px;
  margin: 0 auto;
  text-align: center;
}

.actions {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 0.8rem;
  margin-top: 1.4rem;
}

.actions.split {
  align-items: center;
  justify-content: space-between;
}

.ghost {
  color: #243150;
  background: #edf3ff;
  box-shadow: none;
}

.notice {
  display: inline-block;
  margin-bottom: 1rem;
  padding: 0.55rem 0.85rem;
  border-radius: 999px;
  color: #4a258a;
  font-weight: 850;
  background: #f0e7ff;
}

.quiz-topline {
  display: flex;
  justify-content: space-between;
  gap: 1rem;
  margin-bottom: 0.8rem;
  color: #52617b;
  font-weight: 900;
}

.progress-track {
  height: 0.65rem;
  overflow: hidden;
  border-radius: 999px;
  background: #dfe8f8;
}

.progress-track span {
  display: block;
  height: 100%;
  border-radius: inherit;
  background: linear-gradient(90deg, #6b5cff, #00c2ff);
  transition: width 0.25s ease;
}

.question {
  margin: 1.6rem 0;
}

.options {
  display: grid;
  gap: 0.8rem;
}

.option {
  display: grid;
  grid-template-columns: 2rem 1fr;
  align-items: center;
  gap: 0.75rem;
  border-radius: 1.1rem;
  padding: 1rem;
  color: #18243e;
  background: white;
  box-shadow: inset 0 0 0 1px #dfe6f3;
  text-align: left;
}

.option b {
  display: grid;
  width: 2rem;
  height: 2rem;
  place-items: center;
  border-radius: 50%;
  color: white;
  background: #7c89a8;
}

.option.selected {
  box-shadow: inset 0 0 0 3px #635bff;
}

.option.correct {
  color: #0f4c2d;
  background: #e7fff1;
  box-shadow: inset 0 0 0 3px #1fc777;
}

.option.wrong {
  color: #7f1b2b;
  background: #fff0f3;
  box-shadow: inset 0 0 0 3px #ff5574;
}

.feedback {
  margin-top: 1rem;
  padding: 1.2rem;
  border-radius: 1.1rem;
  background: #f5f8ff;
}

.feedback p {
  margin-bottom: 0;
  color: #55647a;
}

.results {
  max-width: 760px;
  margin: 0 auto;
  text-align: center;
}

.achievement-box {
  margin-top: 1.2rem;
  padding: 1.2rem;
  border-radius: 1.2rem;
  background: linear-gradient(135deg, #f4f7ff, #fff8ec);
}

.badge {
  display: inline-block;
  margin: 0.25rem;
  padding: 0.65rem 0.9rem;
  border-radius: 999px;
  color: #fff;
  font-weight: 900;
  background: linear-gradient(135deg, #ff9f1c, #ff3d7f);
}

@media (max-width: 700px) {
  .hero, .section-heading, .quiz-topline, .actions.split {
    align-items: stretch;
    flex-direction: column;
  }

  .score-orb {
    width: 100%;
    height: auto;
    padding: 1.2rem;
    border-radius: 1.2rem;
  }
}
