{"filePath": "/app/public/app.js", "content": "const app = document.getElementById('app');
let unlockedPassword = sessionStorage.getItem('notesUnlockedPassword') || '';
let notes = [];
let currentNote = null;
let currentBody = '';
let saving = Promise.resolve();

function api(path, options = {}) {
  return fetch(path, {
    ...options,
    headers: {
      'Content-Type': 'application/json',
      'x-notes-password': unlockedPassword,
      ...(options.headers || {})
    }
  });
}

function formatDate(value) {
  const date = new Date(value);
  const pad = (n) => String(n).padStart(2, '0');
  return `${date.getUTCFullYear()}-${pad(date.getUTCMonth() + 1)}-${pad(date.getUTCDate())} ${pad(date.getUTCHours())}:${pad(date.getUTCMinutes())}`;
}

function noteTitle(body) {
  const first = body.split('\n').find((line) => line.trim());
  return first ? first.trim() : 'New Note';
}

function notePreview(body) {
  const lines = body.split('\n');
  const titleIndex = lines.findIndex((line) => line.trim());
  const remaining = titleIndex === -1 ? [] : lines.slice(titleIndex + 1);
  const text = remaining.join(' ').trim();
  return text || 'No additional text';
}

function escapeHtml(text) {
  return text.replace(/[&<>"]/g, (char) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[char]));
}

function setRoute(path) {
  history.pushState(null, '', path);
  render();
}

async function loadNotes() {
  const response = await api('/api/notes');
  if (response.status === 401) {
    lock();
    return;
  }
  const data = await response.json();
  notes = data.notes;
}

function lock() {
  unlockedPassword = '';
  sessionStorage.removeItem('notesUnlockedPassword');
  renderGate();
}

function renderGate(error = '') {
  app.innerHTML = `
    <section class="gate" data-testid="section-password-gate">
      <form class="gate-card" data-testid="form-unlock">
        <div class="brand">
          <div class="logo" data-testid="text-logo">N</div>
          <div>
            <h1 data-testid="text-app-title">Notes</h1>
            <p class="subtitle" data-testid="text-app-subtitle">A private space for plain text thoughts.</p>
          </div>
        </div>
        <div class="form-row">
          <label for="password" data-testid="text-password-label">Password</label>
          <input id="password" data-testid="input-password" type="password" autocomplete="current-password" autofocus>
          <button class="primary" data-testid="button-unlock" type="submit">Unlock notes</button>
          <div class="error" data-testid="text-password-error">${escapeHtml(error)}</div>
        </div>
      </form>
    </section>
  `;
  const form = app.querySelector('form');
  const input = app.querySelector('#password');
  form.addEventListener('submit', async (event) => {
    event.preventDefault();
    const password = input.value;
    const response = await fetch('/api/unlock', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ password })
    });
    if (!response.ok) {
      const data = await response.json().catch(() => ({ error: 'Incorrect password' }));
      renderGate(data.error || 'Incorrect password');
      return;
    }
    unlockedPassword = password;
    sessionStorage.setItem('notesUnlockedPassword', password);
    await loadNotes();
    render();
  });
}

function renderShell(content) {
  app.innerHTML = `<section class="shell" data-testid="section-notes-app">${content}</section>`;
}

function renderList() {
  const query = new URLSearchParams(location.search).get('q') || '';
  const normalized = query.toLowerCase();
  const filtered = notes.filter((note) => {
    const title = noteTitle(note.body).toLowerCase();
    return !normalized || title.includes(normalized) || note.body.toLowerCase().includes(normalized);
  });
  renderShell(`
    <div class="topbar">
      <div>
        <h1 data-testid="text-list-title">Your notes</h1>
        <p class="subtitle" data-testid="text-note-count">${filtered.length} ${filtered.length === 1 ? 'note' : 'notes'}</p>
      </div>
      <div class="actions">
        <button class="primary" data-testid="button-new-note">New Note</button>
      </div>
    </div>
    <div class="panel">
      <div class="search-wrap">
        <input data-testid="input-search" type="search" placeholder="Search notes" value="${escapeHtml(query)}">
      </div>
      <div class="list" data-testid="list-notes">
        ${filtered.length ? filtered.map((note) => `
          <div class="note-row" data-testid="row-note-${note.id}">
            <button class="note-open" data-testid="button-open-note-${note.id}" data-id="${note.id}">
              <p class="note-title" data-testid="text-title-${note.id}">${escapeHtml(noteTitle(note.body))}</p>
              <div class="note-preview" data-testid="text-preview-${note.id}">${escapeHtml(notePreview(note.body))}</div>
            </button>
            <div class="timestamp" data-testid="text-timestamp-${note.id}">${formatDate(note.updated_at)}</div>
            <button class="danger" data-testid="button-delete-note-${note.id}" data-delete="${note.id}">Delete</button>
          </div>
        `).join('') : '<div class="empty" data-testid="text-empty-state">No notes yet. Create your first note.</div>'}
      </div>
    </div>
  `);
  app.querySelector('[data-testid="button-new-note"]').addEventListener('click', createNote);
  app.querySelector('[data-testid="input-search"]').addEventListener('input', (event) => {
    const value = event.target.value;
    history.replaceState(null, '', value ? `/?q=${encodeURIComponent(value)}` : '/');
    renderList();
  });
  app.querySelectorAll('[data-id]').forEach((button) => button.addEventListener('click', () => setRoute(`/notes/${button.dataset.id}`)));
  app.querySelectorAll('[data-delete]').forEach((button) => button.addEventListener('click', (event) => {
    event.stopPropagation();
    deleteNote(button.dataset.delete, false);
  }));
}

async function createNote() {
  const response = await api('/api/notes', { method: 'POST', body: JSON.stringify({}) });
  const data = await response.json();
  notes.unshift(data.note);
  setRoute(`/notes/${data.note.id}`);
}

async function saveCurrent() {
  if (!currentNote || currentBody === currentNote.body) return saving;
  const id = currentNote.id;
  const body = currentBody;
  saving = api(`/api/notes/${id}`, { method: 'PUT', body: JSON.stringify({ body }) })
    .then((response) => response.ok ? response.json() : Promise.reject())
    .then((data) => {
      const index = notes.findIndex((note) => note.id === id);
      if (index !== -1) notes[index] = data.note;
      currentNote = data.note;
      currentBody = data.note.body;
    });
  return saving;
}

async function renderEditor(id) {
  let note = notes.find((item) => item.id === id);
  if (!note) {
    const response = await api(`/api/notes/${id}`);
    if (response.status === 404) {
      setRoute('/');
      return;
    }
    const data = await response.json();
    note = data.note;
  }
  currentNote = note;
  currentBody = note.body;
  renderShell(`
    <div class="topbar">
      <div>
        <h1 data-testid="text-editor-title">${escapeHtml(noteTitle(note.body))}</h1>
        <p class="subtitle" data-testid="text-editor-timestamp">Last edited ${formatDate(note.updated_at)} UTC</p>
      </div>
      <div class="actions">
        <button class="ghost" data-testid="button-back-list">Back</button>
        <button class="danger" data-testid="button-delete-current">Delete</button>
      </div>
    </div>
    <div class="panel editor-panel">
      <textarea data-testid="input-note-body" placeholder="Start typing...">${escapeHtml(note.body)}</textarea>
      <div class="meta" data-testid="status-autosave">Autosaves when you leave this note.</div>
    </div>
  `);
  const textarea = app.querySelector('textarea');
  textarea.focus();
  textarea.setSelectionRange(textarea.value.length, textarea.value.length);
  textarea.addEventListener('input', (event) => {
    currentBody = event.target.value;
  });
  app.querySelector('[data-testid="button-back-list"]').addEventListener('click', async () => {
    await saveCurrent();
    currentNote = null;
    setRoute('/');
  });
  app.querySelector('[data-testid="button-delete-current"]').addEventListener('click', () => deleteNote(id, true));
}

async function deleteNote(id, fromEditor) {
  const ok = confirm('Permanently delete this note? This cannot be undone.');
  if (!ok) return;
  await api(`/api/notes/${id}`, { method: 'DELETE' });
  notes = notes.filter((note) => note.id !== id);
  if (fromEditor || location.pathname === `/notes/${id}`) {
    currentNote = null;
    setRoute('/');
  } else {
    renderList();
  }
}

async function render() {
  if (!unlockedPassword) {
    renderGate();
    return;
  }
  if (!notes.length) await loadNotes();
  const match = location.pathname.match(/^\/notes\/([^/]+)$/);
  if (match) {
    await renderEditor(match[1]);
  } else {
    currentNote = null;
    renderList();
  }
}

window.addEventListener('popstate', async () => {
  await saveCurrent();
  render();
});

window.addEventListener('beforeunload', (event) => {
  if (!currentNote || currentBody === currentNote.body) return;
  navigator.sendBeacon(`/api/notes/${currentNote.id}`, new Blob([JSON.stringify({ body: currentBody })], { type: 'application/json' }));
});

render();
"}

