const pool = new Pool({ connectionString: process.env.POSTGRES_DATABASE_URL });

async function main() {
  await pool.query(`
    CREATE TABLE IF NOT EXISTS products (
      id BIGSERIAL PRIMARY KEY,
      seller_token TEXT UNIQUE NOT NULL,
      title TEXT NOT NULL,
      description TEXT NOT NULL,
      price_cents INTEGER NOT NULL CHECK (price_cents >= 1),
      category TEXT NOT NULL,
      condition TEXT NOT NULL,
      location TEXT NOT NULL,
      image_path TEXT NOT NULL,
      seller_name TEXT NOT NULL,
      seller_email TEXT NOT NULL,
      status TEXT NOT NULL DEFAULT 'available' CHECK (status IN ('available', 'pending', 'sold')),
      created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
      updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
    )
  `);
  await pool.query(`
    CREATE TABLE IF NOT EXISTS orders (
      id BIGSERIAL PRIMARY KEY,
      product_id BIGINT NOT NULL REFERENCES products(id) ON DELETE CASCADE,
      buyer_token TEXT UNIQUE NOT NULL,
      buyer_name TEXT NOT NULL,
      buyer_email TEXT NOT NULL,
      buyer_phone TEXT NOT NULL,
      status TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'confirmed', 'cancelled')),
      created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
      updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
    )
  `);
  await pool.query('CREATE INDEX IF NOT EXISTS idx_products_status_created ON products(status, created_at DESC)');
  await pool.query('CREATE INDEX IF NOT EXISTS idx_products_category ON products(category)');
  await pool.query('CREATE INDEX IF NOT EXISTS idx_orders_product ON orders(product_id)');
}

main().then(() => pool.end()).catch(async (error) => {
  console.error(error);
  await pool.end();
  process.exit(1);
});
"}

