const uploadDir = path.join(__dirname, 'uploads');
fs.mkdirSync(uploadDir, { recursive: true });

const categories = ['Electronics', 'Fashion', 'Home & Garden', 'Vehicles', 'Collectibles', 'Sports', 'Books', 'Other'];
const conditions = ['new', 'like-new', 'good', 'fair'];
const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
const storage = multer.diskStorage({
  destination: uploadDir,
  filename: (req, file, cb) => cb(null, `${Date.now()}-${crypto.randomBytes(8).toString('hex')}${path.extname(file.originalname || '.jpg')}`)
});
const upload = multer({
  storage,
  limits: { fileSize: 8 * 1024 * 1024 },
  fileFilter: (req, file, cb) => cb(null, file.mimetype.startsWith('image/'))
});

app.use(express.urlencoded({ extended: true }));
app.use('/uploads', express.static(uploadDir));

function token() {
  return crypto.randomBytes(32).toString('base64url');
}

function money(cents) {
  return `$${(Number(cents) / 100).toFixed(2)}`;
}

function escapeHtml(value) {
  return String(value ?? '').replace(/[&<>"']/g, (char) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[char]));
}

function priceToCents(value) {
  if (!/^\d+(\.\d{1,2})?$/.test(String(value || '').trim())) return null;
  const cents = Math.round(Number(value) * 100);
  return cents >= 1 ? cents : null;
}

function statusText(product, order) {
  if (order?.status === 'confirmed' || product.status === 'sold') return 'Sold';
  if (order?.status === 'cancelled') return 'Cancelled';
  if (product.status === 'pending') return 'Pending order';
  return 'Available';
}

function layout(title, body) {
  return `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${escapeHtml(title)} · LinkMarket</title><style>
    :root{color-scheme:light;--ink:#152033;--muted:#667085;--bg:#f6f8fb;--card:#fff;--line:#e6eaf0;--brand:#5b5ce2;--brand2:#00a7a7;--bad:#c0362c;--good:#11845b;--warn:#b76e00}*{box-sizing:border-box}body{margin:0;font-family:Inter,ui-sans-serif,system-ui,-apple-system,Segoe UI,Arial;background:radial-gradient(circle at top left,#e9ecff,transparent 30%),var(--bg);color:var(--ink)}a{color:inherit}header{padding:24px min(6vw,72px);display:flex;justify-content:space-between;align-items:center}.logo{font-weight:900;font-size:24px;text-decoration:none;letter-spacing:-.04em}.nav{display:flex;gap:10px;flex-wrap:wrap}.btn,button{border:0;border-radius:14px;padding:12px 18px;background:var(--brand);color:#fff;font-weight:800;text-decoration:none;cursor:pointer;box-shadow:0 10px 22px rgba(91,92,226,.18)}.btn.alt{background:#fff;color:var(--ink);border:1px solid var(--line);box-shadow:none}.btn.warn,button.warn{background:var(--bad)}main{padding:0 min(6vw,72px) 64px}.hero{display:grid;grid-template-columns:1.2fr .8fr;gap:28px;align-items:center;padding:42px 0}.panel,.card{background:rgba(255,255,255,.92);border:1px solid var(--line);border-radius:26px;box-shadow:0 18px 60px rgba(21,32,51,.08)}.panel{padding:30px}h1{font-size:clamp(38px,6vw,74px);line-height:.92;letter-spacing:-.07em;margin:0 0 18px}h2{font-size:32px;letter-spacing:-.04em;margin:26px 0 14px}p{color:var(--muted);line-height:1.6}.grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(240px,1fr));gap:18px}.card{overflow:hidden;text-decoration:none}.card img,.detail-img{width:100%;height:205px;object-fit:cover;background:#dfe3ea}.card-body{padding:16px}.price{font-size:24px;font-weight:900}.meta{color:var(--muted);font-size:14px}.chips{display:flex;flex-wrap:wrap;gap:10px}.chip,.badge{display:inline-flex;align-items:center;border-radius:999px;padding:8px 12px;background:#fff;border:1px solid var(--line);text-decoration:none;font-weight:800;font-size:13px}.badge.new{background:#e9fff5;color:#08704c}.badge.like-new{background:#edf0ff;color:#3d45bd}.badge.good{background:#ecfbff;color:#006b80}.badge.fair{background:#fff4e1;color:#8c5100}.status{padding:12px 14px;border-radius:16px;font-weight:900;background:#eef0ff;color:#3730a3;display:inline-block}.status.sold,.status.cancelled{background:#ffecec;color:#9f1d16}.status.available,.status.confirmed{background:#e8fff4;color:#08704c}form{display:grid;gap:14px}.field{display:grid;gap:7px}label{font-weight:800}input,textarea,select{width:100%;border:1px solid var(--line);border-radius:14px;padding:13px 14px;font:inherit;background:#fff}textarea{min-height:130px}.split{display:grid;grid-template-columns:1fr 1fr;gap:18px}.notice{padding:14px 16px;border-radius:16px;background:#fff8e8;border:1px solid #f5d28d;color:#6d4700}.error{padding:14px 16px;border-radius:16px;background:#ffecec;border:1px solid #ffc0bd;color:#8a1f17}.success{padding:14px 16px;border-radius:16px;background:#e8fff4;border:1px solid #a8edcf;color:#096646}.linkbox{word-break:break-all;font-weight:800;background:#f1f4f9;padding:14px;border-radius:14px}@media(max-width:760px){.hero,.split{grid-template-columns:1fr}header{align-items:flex-start;gap:12px;flex-direction:column}}
  </style></head><body><header><a class="logo" data-testid="link-home" href="/">LinkMarket</a><nav class="nav"><a class="btn alt" data-testid="link-browse" href="/browse">Browse</a><a class="btn" data-testid="link-sell" href="/sell">Sell an item</a></nav></header><main>${body}</main></body></html>`;
}

